function tempo(code) {
  if (code === 0) return "céu limpo";
  if (code === 1) return "predominantemente limpo";
  if (code === 2) return "parcialmente nublado";
  if (code === 3) return "nublado";
  if (code === 45 || code === 48) return "neblina";
  if (code >= 51 && code <= 57) return "garoa";
  if (code >= 61 && code <= 67) return "chuva";
  if (code >= 71 && code <= 77) return "neve";
  if (code >= 80 && code <= 82) return "pancadas de chuva";
  if (code === 85 || code === 86) return "pancadas de neve";
  if (code >= 95) return "trovoadas";
  return "";
}

async function run() {
  const w = await http.getJSON("https://api.open-meteo.com/v1/forecast?latitude=" + params.cidade.latitude + "&longitude=" + params.cidade.longitude + "&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=auto&forecast_days=7");
  const d = w && w.daily;
  if (!d || !d.time) {
    log("Previsão indisponível.");
    return;
  }
  const hoje = dates.today().slice(0, 10);
  const linhas = [];
  let choveAlgumDia = false;
  for (let i = 0; i < d.time.length && linhas.length < 2; i++) {
    const dia = d.time[i];
    if (dia < hoje) continue;
    const wd = dates.weekday(dia);
    if (wd !== 6 && !(wd === 0 && (linhas.length === 1 || dia === hoje))) continue;
    const chance = d.precipitation_probability_max ? d.precipitation_probability_max[i] : null;
    const chove = typeof chance === "number" && chance >= params.chuva;
    if (chove) choveAlgumDia = true;
    let linha = (chove ? "☔ " : "• ") + (wd === 6 ? "Sábado" : "Domingo") + " (" + dates.format(dia, "d/MM") + "): " +
      Math.round(d.temperature_2m_min[i]) + "° a " + Math.round(d.temperature_2m_max[i]) + "°";
    const t = d.weather_code ? tempo(d.weather_code[i]) : "";
    if (t) linha += ", " + t;
    if (typeof chance === "number") linha += ", " + chance + "% de chuva";
    linhas.push(linha);
  }
  if (linhas.length === 0) {
    log("A previsão não chega ao fim de semana.");
    return;
  }
  if (params.so_com_chuva && !choveAlgumDia) {
    log("Fim de semana sem chuva prevista.");
    return;
  }
  await notify.send({text: "🌤️ Fim de semana em " + params.cidade.name + ":\n" + linhas.join("\n")});
}
